CREATE TABLE teams (team_id TEXT PRIMARY KEY, team_name TEXT NOT NULL);
CREATE TABLE queue_items (item_id TEXT PRIMARY KEY, team_id TEXT REFERENCES teams(team_id), state TEXT NOT NULL CHECK (state IN ('waiting','processing','closed','canceled')), received_on TEXT NOT NULL, due_on TEXT, value_cents INTEGER NOT NULL CHECK (value_cents >= 0));
